'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16"/>',chart:'<path d="M4 4v16h17M8 15v-4m5 4V7m5 8v-7"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4v17h17v-6"/>',history:'<path d="M3 4v5h5M3 9a9 9 0 1 1 0 7m9-10v6l4 2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.chart}</svg>`;
const tabs=['Todos los Prompts','Análisis Competitivo','Recomendaciones','Referencias y Fuentes','Brand Intelligence'];
const state={tab:0,page:1,query:'',sort:null,dir:1,kpi:0,kpiTouched:false,range:'6m',chartMetric:'sov',historyMetric:'sov',selected:new Set(DATA.prompts.map(p=>p.id)),visible:new Set(DATA.currentRanking.items.map(b=>b.brand)),expanded:new Set(),recExpanded:new Set(),recStatus:'Todas',recPriority:'Todas',audit:[],biPrompt:'all',biMonth:'2026-09'};
let lastFocus=null;
const promptMap=new Map(DATA.prompts.map(p=>[p.id,p]));
const historyMap=new Map(DATA.history.map(h=>[h.promptId+'|'+h.date,h]));
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function dateLabel(d,year=false){return new Date(d+'T12:00:00').toLocaleDateString('es-PE',{day:'numeric',month:'short',...(year?{year:'numeric'}:{})}).replaceAll('.','')}
function position(p){return p.status==='error'?'<span class="tag red">Error</span>':p.position===1?'<span class="tag gold">★ #1</span>':p.position?`<span class="position">#${p.position}</span>`:'<span class="position muted">No mencionada</span>'}
function modal(html){lastFocus=document.activeElement;$('#modalContent').innerHTML=html;$('#modal').showModal();$('#modal').scrollTop=0;$('.close-x')?.focus()}
function modalShell(title,body,wide=false){if(wide)$('#modal').style.width='min(1000px,calc(100% - 32px))';else $('#modal').style.width='';modal(`<div class="modal-head"><h2>${title}</h2><button class="close-x" data-close aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div><div class="modal-footer"><button class="button primary" data-close>Cerrar</button></div>`)}
function showResponse(id,date=null){const p=promptMap.get(id);const h=date?historyMap.get(id+'|'+date):null;let body=`<p class="prompt-quote">“${esc(p.text)}”</p>`;if(h){const labels={not_run:'Sin análisis',error:'Error de análisis',no_brands:'Sin marcas mencionadas',brand_not_mentioned:'Marca no mencionada'};body+=`<p class="small muted">${dateLabel(date,true)} · ChatGPT</p>`;if(h.state!=='ok'){body+=`<div class="empty"><h3>${labels[h.state]}</h3><p>No hay una respuesta literal disponible para este registro.</p></div>`;modalShell('✦ Respuesta del LLM (ChatGPT)',body);return}}
 body+=`<div style="display:flex;align-items:center;gap:10px;margin-top:14px">${position(h?{...p,position:h.position,status:'ok'}:p)}<b class="small">${h?h.sov:p.sov??'—'}${(h?h.sov:p.sov)!==null?'%':''} SOV</b></div><div class="sample-banner">Respuesta de ejemplo · El texto literal no se incluyó en los archivos fuente.</div><div class="response-text">${esc(p.response.text)}</div><h3 class="section-label" style="margin-top:28px">Captura de pantalla</h3><div class="screenshot">Sin captura guardada para este análisis.</div>`;modalShell('✦ Respuesta del LLM (ChatGPT)',body)}
function renderConfig(){const days=Math.max(0,Math.floor((Date.now()-Date.parse(DATA.project.lastUpdate))/86400000));$('#config').innerHTML=`<div class="config-item"><div class="eyebrow">Modelo de IA</div><div class="config-value"><span class="tag purple">✦ ChatGPT</span></div></div><div class="config-item"><div class="eyebrow">Prompts activos</div><div class="config-value">${DATA.project.activePrompts}</div></div><div class="config-item"><div class="eyebrow">País</div><div class="config-value"><span class="tag">PE</span> Perú</div></div><div class="config-item"><div class="eyebrow">Última actualización</div><div class="config-value" title="14 de julio de 2026">${icon('clock')} Hace ${days}d</div></div>`}
function renderKpis(){const sov=state.kpiTouched?DATA.kpis.sovAvg[state.range]:DATA.kpis.sovAvg['1m'];const ks=[['Aparición Temprana',DATA.kpis.earlyAppearance,'de 37','Prompts donde BCP aparece en el primer tercio de la respuesta de IA, indicando mayor prominencia'],['Primera Mención',DATA.kpis.firstMention,'de 37','Prompts donde BCP es el primer competidor mencionado en la respuesta de IA'],['SOV Promedio',sov===null?'—':sov+'%','','Share of Voice promedio de BCP en todos los prompts analizados'],['Posicionamiento',DATA.kpis.avgPosition,'','Posición promedio de BCP entre los competidores mencionados en las respuestas de IA. Valor más bajo = mejor posicionamiento.'],['Presencia de Marca','—','','Prompts donde tu marca aparece en al menos 1 de los 3 trackeos semanales','prompts con mención esta semana'],['1ª Mención Semanal','—','','Prompts donde la posición promedio de tu marca es menor a 3 esta semana','pos. prom. < 3 esta semana']];const mobile=innerWidth<768;const count=mobile?1:4;const max=mobile?5:2;state.kpi=Math.min(state.kpi,max);$('#kpis').innerHTML=ks.slice(state.kpi,state.kpi+count).map(k=>`<article class="card kpi"><div class="kpi-label">${k[0]}<button class="info" data-tip="${esc(k[3])}" aria-label="${esc(k[3])}"></button></div><div class="kpi-value">${k[1]}<small>${k[2]}</small>${k[4]?`<span class="muted" style="margin-left:auto">${icon('calendar')}</span>`:''}</div>${k[4]?`<p class="kpi-sub">${k[4]}</p>`:''}</article>`).join('');$('#dots').innerHTML=Array.from({length:max+1},(_,i)=>`<button class="dot ${i===state.kpi?'active':''}" data-kpi="${i}" aria-label="Página ${i+1} de indicadores" ${i===state.kpi?'aria-current="true"':''}></button>`).join('');$('#kpiPrev').disabled=state.kpi===0;$('#kpiNext').disabled=state.kpi===max}
function renderTabs(){$('#tabs').innerHTML=tabs.map((t,i)=>`<button id="tab${i}" role="tab" aria-controls="view" aria-selected="${state.tab===i}" tabindex="${state.tab===i?0:-1}" class="tab ${state.tab===i?'active':''}" data-tab="${i}">${t}</button>`).join('');$('#view').setAttribute('aria-labelledby','tab'+state.tab)}
function render(){renderTabs();[renderPrompts,renderCompetitive,renderRecs,renderReferences,renderBI][state.tab]()}
function filteredPrompts(){let list=DATA.prompts.filter(p=>p.text.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(state.query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase()));if(state.sort)list=[...list].sort((a,b)=>{if(a[state.sort]===null&&b[state.sort]===null)return 0;if(a[state.sort]===null)return 1;if(b[state.sort]===null)return -1;return (a[state.sort]-b[state.sort])*state.dir});return list}
function renderPrompts(){const list=filteredPrompts();const pages=Math.max(1,Math.ceil(list.length/10));state.page=Math.min(state.page,pages);const start=(state.page-1)*10;$('#view').innerHTML=`<div class="view-header"><h2>Performance por Prompt</h2><label class="search">${icon('search')}<input id="promptSearch" type="search" placeholder="Buscar prompt..." aria-label="Buscar prompt" value="${esc(state.query)}"></label></div><div class="card"><div class="table-scroll"><table class="prompt-table"><thead><tr><th>Prompt</th>${[['position','Posición'],['linkPosition','Enlace'],['sov','Visibilidad (SOV)']].map(([key,label])=>`<th aria-sort="${state.sort===key?(state.dir===1?'ascending':'descending'):'none'}"><button class="sort" data-sort="${key}">${label}<span>${state.sort===key?(state.dir===1?'↑':'↓'):'⇅'}</span></button></th>`).join('')}<th>Ranking de marcas</th><th>Detalle</th></tr></thead><tbody>${list.slice(start,start+10).map(p=>`<tr><td>${esc(p.text)}</td><td>${position(p)}</td><td>${p.status==='error'?'<span class="muted">—</span>':p.linkPosition?`<span class="tag">#${p.linkPosition}</span>`:'<span class="small muted">Sin enlace</span>'}</td><td class="sov">${p.sov===null?'<span class="muted">—</span>':p.sov+'%'}</td><td><div class="rank-lines">${(state.expanded.has(p.id)?p.ranking:p.ranking.slice(0,3)).map((b,i)=>`<div><span class="rank-num">#${i+1}</span> ${b==='BCP'?`<b>${esc(b)}</b>`:esc(b)}</div>`).join('')||'<span class="muted">—</span>'}</div>${p.ranking.length>3?`<button class="text-button more" data-rank="${p.id}" aria-expanded="${state.expanded.has(p.id)}">${state.expanded.has(p.id)?'Ver menos ⌃':`Ver ${p.ranking.length-3} más ⌄`}</button>`:''}</td><td><button class="text-button" data-detail="${p.id}">Ver detalle</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><h3>Sin resultados</h3><p>Prueba con otro término de búsqueda.</p></div></td></tr>'}</tbody></table></div><div class="pagination"><span>Mostrando ${list.length?start+1:0} a ${Math.min(start+10,list.length)} de ${list.length} prompts</span><div class="pages"><button class="page-btn" data-page="-1" ${state.page===1?'disabled':''} aria-label="Página anterior">‹</button><span class="page-num">${state.page} / ${pages}</span><button class="page-btn" data-page="1" ${state.page===pages?'disabled':''} aria-label="Página siguiente">›</button></div></div></div>`}
function metricSegment(current,group,history=false){return `<div class="segment light">${[['sov',history?'SOV%':'SOV'],['position','Posición'],['linkPosition','Pos. Enlace']].map(([k,v])=>`<button data-${group}="${k}" class="${current===k?'active':''}" aria-pressed="${current===k}">${v}</button>`).join('')}</div>`}
function selectedLabel(){return state.selected.size===37?'Todos los prompts (37)':`${state.selected.size} prompts seleccionados`}
function renderCompetitive(){state.kpiTouched=true;renderKpis();$('#view').innerHTML=`<div class="view-header"><div><h2>Evolución de la Competencia</h2><p>Compara el rendimiento de BCP frente a la competencia</p></div></div><div class="toolbar"><div class="multi"><button class="button" id="multiToggle" aria-expanded="false">${icon('search')} ${selectedLabel()} <span class="muted">⌄</span></button><div id="multiPanel" class="multi-panel" hidden><div style="display:flex;justify-content:space-between;gap:12px"><span class="eyebrow" style="margin:0">Seleccionar prompts</span><button class="text-button" id="selectAll">${state.selected.size?'Deseleccionar todas':'Seleccionar todas'}</button></div><div class="multi-list">${[...DATA.prompts].sort((a,b)=>(b.sov??-1)-(a.sov??-1)).map((p,i)=>`<label class="multi-label"><input type="checkbox" data-select="${p.id}" ${state.selected.has(p.id)?'checked':''}><span><b style="color:${i===0?'#ba850c':i===1?'#8995a6':i===2?'#a3764c':'#8792a4'}">#${i+1}</b> ${esc(p.text)}</span><small>SOV: ${p.sov??'—'}${p.sov!==null?'%':''}</small></label>`).join('')}</div></div></div><div class="segment">${[['1m','1 mes'],['3m','3 meses'],['6m','6 meses']].map(([k,v])=>`<button data-range="${k}" class="${state.range===k?'active':''}" aria-pressed="${state.range===k}">${v}</button>`).join('')}</div></div><div class="competitive"><article class="card chart-card" id="chartCard"><div class="card-head"><h3>Evolución Comparativa</h3><button class="fullscreen-btn" id="fullscreen" aria-label="Ampliar gráfico">${icon('expand')}</button></div><div class="chart-tools">${metricSegment(state.chartMetric,'chartmetric')}<span class="small muted" id="pointCount">12 puntos de datos</span></div><div id="chart" class="chart-area"></div><p class="note">Última serie disponible: 8 jul 2026 · Sin nuevas corridas desde el 14 jul</p></article><aside class="card ranking"><div class="card-head"><h3>RANKING ACTUAL</h3><small>al 20 oct</small></div><div class="ranking-list">${DATA.currentRanking.items.map(b=>`<div class="rank-row"><span class="color-dot" style="background:${b.color}"></span><span class="rank-name">${esc(b.brand)}</span><span class="rank-value" style="color:${b.color}">${b.sov}%</span><button class="switch ${state.visible.has(b.brand)?'on':''}" role="switch" aria-checked="${state.visible.has(b.brand)}" aria-label="Mostrar ${esc(b.brand)}" data-brand="${esc(b.brand)}"></button></div>`).join('')}</div><p class="note">Datos de la corrida del 8 jul 2026</p></aside></div><section class="history"><div class="view-header"><div><h2>Historial de Respuestas IA</h2><p>Clic en celda para ver respuesta completa</p></div>${metricSegment(state.historyMetric,'historymetric',true)}</div><div class="sample-banner">Historial de ejemplo · Valores simulados para mostrar la navegación; reemplazar con el export real.</div><div class="card table-scroll" id="historyTable"></div></section>`;renderChart();renderHistory()}
function chartData(){if(state.range!=='6m'||state.selected.size!==37||state.chartMetric!=='sov')return [];return DATA.competitorSeries}
function renderChart(){const data=chartData();const dates=[...new Set(data.map(d=>d.date))];$('#pointCount').textContent=dates.length+' puntos de datos';if(!dates.length){const selected=state.selected.size!==37;const message=!state.selected.size?'Selecciona al menos un prompt para ver su evolución.':state.chartMetric!=='sov'?'No se incluyeron series de posición o enlace en los archivos fuente.':selected?'No se incluyeron series históricas individuales en los archivos fuente.':'Este prompt aún no tiene análisis previos. Ejecuta un análisis para comenzar a ver la evolución.';$('#chart').innerHTML=`<div class="empty">${icon('chart')}<h3>Sin datos de tracking</h3><p>${message}</p></div>`;return}
 const W=760,H=290,L=40,R=15,T=16,B=37,x=i=>L+i*(W-L-R)/(dates.length-1),y=v=>T+(50-v)*(H-T-B)/50;
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución del Share of Voice de BCP y competidores entre abril y julio de 2026">`;
 for(let t=0;t<=50;t+=10)svg+=`<path d="M${L} ${y(t)}H${W-R}" stroke="#edf0f6" stroke-width="1"/><text x="${L-9}" y="${y(t)+3}" text-anchor="end" fill="#8a95a7" font-size="9" font-family="Inter,Arial">${t}%</text>`;
 dates.forEach((d,i)=>svg+=`<text x="${x(i)}" y="${H-13}" fill="#8a95a7" text-anchor="middle" font-size="8" font-family="Inter,Arial">${dateLabel(d)}</text>`);
 DATA.currentRanking.items.forEach(b=>{const vals=dates.map(d=>data.find(v=>v.date===d&&v.brand===b.brand)?.sov??null);if(!state.visible.has(b.brand)||vals.every(v=>v===null))return;const points=vals.map((v,i)=>v===null?null:[x(i),y(v)]).filter(Boolean);svg+=`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${b.color}" stroke-width="${b.brand==='BCP'?2.7:1.8}" stroke-linecap="round" stroke-linejoin="round"/>`;points.forEach(p=>svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="${b.brand==='BCP'?3.4:2.5}" fill="${b.color}" stroke="white" stroke-width="1"/>`)});
 dates.forEach((d,i)=>svg+=`<rect x="${x(i)-25}" y="0" width="50" height="${H-B}" fill="transparent" data-chartdate="${d}" tabindex="0" role="button" aria-label="Ver valores del ${dateLabel(d)}"/>`);svg+='</svg><div id="chartTooltip" class="tooltip-chart" hidden></div>';$('#chart').innerHTML=svg;
 $$('[data-chartdate]').forEach(el=>{const show=()=>{const d=el.dataset.chartdate;const tip=$('#chartTooltip');tip.innerHTML=`<strong>${dateLabel(d,true)}</strong>${DATA.currentRanking.items.map(b=>{const val=data.find(v=>v.date===d&&v.brand===b.brand)?.sov;return `<div class="tip-row"><span class="color-dot" style="background:${b.color}"></span>${esc(b.brand)}<b>${val===undefined?'—':val+'%'}</b></div>`}).join('')}`;tip.hidden=false;tip.style.left=Math.max(0,Math.min($('#chart').clientWidth-205,Number(el.getAttribute('x'))/W*$('#chart').clientWidth))+'px'};el.onmouseenter=show;el.onfocus=show;el.onmouseleave=()=>$('#chartTooltip').hidden=true;el.onblur=()=>$('#chartTooltip').hidden=true})}
function renderHistory(){const list=DATA.prompts.filter(p=>state.selected.has(p.id));$('#historyTable').innerHTML=`<table class="history-table"><thead><tr><th>Prompt</th>${DATA.historyDates.map(d=>`<th>${dateLabel(d,true).toUpperCase()}</th>`).join('')}</tr></thead><tbody>${list.map(p=>`<tr><td>${esc(p.text)}</td>${DATA.historyDates.map(d=>{const h=historyMap.get(p.id+'|'+d);const labels={not_run:'Sin análisis',error:'Error',no_brands:'Sin marcas mencionadas',brand_not_mentioned:'Marca no mencionada'};const val=h[state.historyMetric];return `<td><button class="cell-button" data-detail="${p.id}" data-date="${d}">${h.state==='ok'?`<span class="cell-main">${val===null?'—':state.historyMetric==='sov'?val+'%':'#'+val}</span><span class="check">✓</span><span class="llm-chip">ChatGPT</span>`:`<span class="${h.state==='error'?'red':'muted'} small" style="font-style:${h.state==='not_run'?'italic':'normal'}">${h.state==='error'?'⊗ ':''}${labels[h.state]}</span>`}</button></td>`}).join('')}</tr>`).join('')||`<tr><td colspan="20"><div class="empty">Selecciona al menos un prompt.</div></td></tr>`}</tbody></table>`}
function renderRecs(){const recs=DATA.recommendations.filter(r=>(state.recStatus==='Todas'||r.status===state.recStatus)&&(state.recPriority==='Todas'||r.priority===state.recPriority));const pending=DATA.recommendations.filter(r=>r.status==='Pendiente').length,progress=DATA.recommendations.filter(r=>r.status==='En Progreso').length;$('#view').innerHTML=`<div class="view-header"><div><h2>Acciones Sugeridas</h2><p>Recomendaciones priorizadas para mejorar el posicionamiento en respuestas de IA</p></div><button class="button" id="auditHistory">${icon('history')}Ver historial</button></div><div class="summary-grid">${[['ACCIONES RÁPIDAS',0,'<1 hora cada una',''],['EN PROGRESO',progress,'Tareas activas','amber'],['PENDIENTES',pending,'Por realizar','violet']].map(([label,value,sub,color])=>`<div class="card summary-card"><div class="eyebrow">${label}</div><div class="summary-value ${color}">${value}</div><p>${esc(sub)}</p></div>`).join('')}</div><div class="filter-row"><span class="filter-label">ESTADO</span>${[['Todas','Todas'],['Pendiente','Pendientes'],['En Progreso','En Progreso'],['Completado','Completadas']].map(([key,label])=>`<button class="chip ${state.recStatus===key?'active':''}" data-recstatus="${key}">${label}</button>`).join('')}</div><div class="filter-row"><span class="filter-label">PRIORIDAD</span>${['Todas','Alta','Media','Baja'].map(key=>`<button class="chip ${state.recPriority===key?'active':''}" data-recpriority="${key}">${key!=='Todas'?`<span class="filter-dot" style="color:${key==='Alta'?'#d02c2a':key==='Media'?'#cc7800':'#1d8b3d'}">●</span>`:''}${key}</button>`).join('')}</div><p class="recs-count">${recs.length} recomendaciones <span style="float:right">Los cambios de estado se guardan durante esta sesión</span></p>${recs.map(r=>`<article class="card rec"><div class="rec-top"><div class="rec-body"><h3>${esc(r.title)}</h3><p class="rec-desc">${esc(r.description)}</p><p class="rec-prompt">Prompt: ${esc(r.promptText)}</p></div><select data-recstate="${r.id}" aria-label="Estado: ${esc(r.title)}">${['Pendiente','En Progreso','Completado'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="rec-bottom"><span class="tag">${esc(r.category)}</span><span class="effort">◷ ${r.effort}</span><span class="impact">• Impacto: +${r.impactSov}% SOV</span><span class="priority ${r.priority}">● ${r.priority}</span><button class="text-button rec-more" data-recexpand="${r.id}" aria-expanded="${state.recExpanded.has(r.id)}">${state.recExpanded.has(r.id)?'Ver menos ⌃':'Ver más ⌄'}</button></div>${state.recExpanded.has(r.id)?`<div class="rec-details"><div><h4>Acciones Específicas</h4><ul>${r.actions.map(a=>`<li><b>${esc(a.title)}:</b> ${esc(a.detail)}</li>`).join('')}</ul></div><div><h4>Métricas a Monitorear</h4><div class="target">Share of Voice objetivo <b>${r.targets.sovFrom}% → ${r.targets.sovTo}%</b></div><div class="target">Posición objetivo <b>#${r.targets.position}</b></div><div class="target">Timeframe estimado <b>${r.targets.timeframe}</b></div></div></div><div class="note">Descripción, acciones y metas ilustrativas. Impacto estimado transcrito del requerimiento; no es una garantía.</div>`:''}</article>`).join('')||'<div class="card empty"><h3>No hay recomendaciones con estos filtros</h3><p>Selecciona otro estado o prioridad.</p></div>'}`}
function referenceRows(){return DATA.prompts.map(p=>{const hs=DATA.historyDates.map(d=>historyMap.get(p.id+'|'+d));return {p,hs,url:p.linkPosition?'https://www.viabcp.com/':null}})}
function renderReferences(){$('#view').innerHTML=`<div class="view-header"><div><h2>Referencias y Fuentes</h2><p>Seguimiento histórico de menciones de marca y enlaces de referencia por prompt</p></div><button class="button green" id="exportReferences">${icon('download')}Exportar a Excel</button></div><div class="sample-banner">Conteos y fuentes de ejemplo · El requerimiento no incluye el export de referencias.</div><div class="card table-scroll"><table class="references"><thead><tr><th rowspan="2">Prompt</th><th rowspan="2">URL</th>${DATA.historyDates.map(d=>`<th colspan="2">${dateLabel(d,true).toUpperCase()}</th>`).join('')}</tr><tr>${DATA.historyDates.map(()=>'<th>Mención</th><th>Enlace</th>').join('')}</tr></thead><tbody>${referenceRows().map(({p,hs,url})=>`<tr><td>${esc(p.text)}</td><td>${url?`<a class="reference-link" href="${url}" target="_blank" rel="noopener noreferrer">${icon('external')}www.viabcp.com</a>`:'<span class="muted">Sin fuentes</span>'}</td>${hs.map((h,i)=>{const older=hs[i+1];const delta=h.mentions!==null&&older?.mentions!==null&&older?.mentions!==undefined?h.mentions-older.mentions:null;return `<td>${h.mentions===null?'—':`<span class="tag success">${h.mentions}</span>${delta?`<span class="delta" style="color:${delta>0?'#1d8b3d':'#d02c2a'}">${delta>0?'↑':'↓'} ${Math.abs(delta)}</span>`:''}`}</td><td>${h.mentions===null?'—':h.links}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderBI(){const months=Array.from({length:11},(_,i)=>{const dt=new Date(2025,10+i,1);return {value:dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0'),label:dt.toLocaleDateString('es-PE',{month:'long',year:'numeric'}).replace(/^./,s=>s.toUpperCase())}});$('#view').innerHTML=`<div class="view-header"><h2>Brand Intelligence</h2></div><div class="card bi-bar"><select id="biPrompt" aria-label="Prompt de Brand Intelligence"><option value="all">Todos los prompts</option>${DATA.prompts.map(p=>`<option value="${p.id}" ${state.biPrompt===p.id?'selected':''}>${esc(p.text)}</option>`).join('')}</select><div class="bi-compare"><b>Octubre 2026</b><span class="muted">vs</span><select id="biMonth" aria-label="Mes de comparación">${months.map(m=>`<option value="${m.value}" ${m.value===state.biMonth?'selected':''}>${m.label}</option>`).join('')}</select></div></div><div id="biContent" class="bi-content"></div>`;renderBIContent()}
function renderBIContent(){const s=state.biPrompt!=='all'?'empty':DATA.brandIntelligence.states[state.biMonth]||'empty';if(s==='error')$('#biContent').innerHTML='<div class="alert"><span>⚠ No se pudieron cargar los KPIs. Intente nuevamente.</span><button class="text-button" id="retryBI">Reintentar</button></div>';else if(s==='empty')$('#biContent').innerHTML=`<div class="card empty">${icon('chart')}<h3>No hay datos KPI para el período seleccionado</h3><p>Selecciona otro mes o prompt para consultar los resultados disponibles.</p></div>`;else {const e=DATA.brandIntelligence.example;$('#biContent').innerHTML=`<div class="sample-banner">Datos de ejemplo · No hay KPIs reales de octubre en las fuentes. Esta comparación ilustra el estado con datos.</div><div class="bi-cards">${[['% aparición',e.appearance],['% mención',e.mention]].map(([label,k])=>`<div class="card bi-card"><h3>${label}</h3><div class="bi-value">${k.current}%</div><p class="impact">↑ ${(k.current-k.previous).toFixed(1)} puntos porcentuales</p><p class="small muted" style="margin-top:9px">Período comparado: ${k.previous}% · Ejemplo</p></div>`).join('')}</div>`}}
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportPrompts(){const rows=[['Prompt','Estado','Posición BCP','Posición enlace','SOV (%)','Ranking de marcas'],...DATA.prompts.map(p=>[p.text,p.status,p.position??'',p.linkPosition??'',p.sov??'',p.ranking.join(' | ')])];const safe=v=>{let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download('BCP_GEO_37_prompts.csv',new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));toast('CSV exportado · 37 prompts')}
// Minimal standards-based XLSX writer: a stored ZIP containing OOXML parts.
function xlsx(rows){const enc=new TextEncoder(),xml=s=>String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));const col=n=>{let s='';do{s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)-1}while(n>=0);return s};const sheet=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>typeof v==='number'?`<c r="${col(j)}${i+1}"><v>${v}</v></c>`:`<c r="${col(j)}${i+1}" t="inlineStr"><is><t>${xml(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData></worksheet>`;const files={'[Content_Types].xml':'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Referencias BCP (ejemplo)" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':sheet};const chunks=[],central=[];let offset=0;const crc=bytes=>{let c=0xffffffff;for(const b of bytes){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0};for(const [name,txt]of Object.entries(files)){const nb=enc.encode(name),bytes=enc.encode(txt),checksum=crc(bytes);const head=new Uint8Array(30+nb.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,checksum,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,nb.length,true);head.set(nb,30);const c=new Uint8Array(46+nb.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint32(16,checksum,true);cv.setUint32(20,bytes.length,true);cv.setUint32(24,bytes.length,true);cv.setUint16(28,nb.length,true);cv.setUint32(42,offset,true);c.set(nb,46);chunks.push(head,bytes);central.push(c);offset+=head.length+bytes.length}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,central.length,true);e.setUint16(10,central.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function exportReferences(){const rows=[['Datos de ejemplo. Conteos y URLs simulados.'],['Prompt','URL',...DATA.historyDates.flatMap(d=>[d+' Mención',d+' Enlace'])],...referenceRows().map(({p,hs,url})=>[p.text,url||'Sin fuentes',...hs.flatMap(h=>[h.mentions??'',h.mentions===null?'':h.links])])];download('BCP_GEO_referencias_ejemplo.xlsx',xlsx(rows));toast('Excel exportado · 37 prompts · Datos de ejemplo')}
function showProjects(){modalShell('Proyectos',`<div class="card project-tile"><div><span class="tag purple">✦ ChatGPT</span><h3 style="margin-top:12px">${esc(DATA.project.name)}</h3><p class="small muted" style="margin-top:6px">BCP · Perú · 37 prompts activos</p></div><button class="button primary" data-close>Abrir proyecto →</button></div>`)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(el.hasAttribute('data-close')){$('#modal').close();return}if(d.tab!==undefined){state.tab=Number(d.tab);render();return}if(d.kpi!==undefined){state.kpi=Number(d.kpi);renderKpis();return}if(d.page){state.page+=Number(d.page);renderPrompts();return}if(d.sort){state.dir=state.sort===d.sort?-state.dir:1;state.sort=d.sort;state.page=1;renderPrompts();return}if(d.rank){state.expanded.has(d.rank)?state.expanded.delete(d.rank):state.expanded.add(d.rank);renderPrompts();return}if(d.detail){showResponse(d.detail,d.date);return}if(d.range){state.range=d.range;state.kpiTouched=true;renderCompetitive();return}if(d.chartmetric){state.chartMetric=d.chartmetric;renderCompetitive();return}if(d.historymetric){state.historyMetric=d.historymetric;const scroll=$('#historyTable').scrollLeft;renderCompetitive();$('#historyTable').scrollLeft=scroll;return}if(d.brand){state.visible.has(d.brand)?state.visible.delete(d.brand):state.visible.add(d.brand);el.classList.toggle('on',state.visible.has(d.brand));el.setAttribute('aria-checked',state.visible.has(d.brand));renderChart();return}if(d.recstatus){state.recStatus=d.recstatus;renderRecs();return}if(d.recpriority){state.recPriority=d.recpriority;renderRecs();return}if(d.recexpand){state.recExpanded.has(d.recexpand)?state.recExpanded.delete(d.recexpand):state.recExpanded.add(d.recexpand);renderRecs();return}switch(el.id){case 'exportPrompts':exportPrompts();break;case 'exportReferences':exportReferences();break;case 'kpiPrev':state.kpi--;renderKpis();break;case 'kpiNext':state.kpi++;renderKpis();break;case 'multiToggle':$('#multiPanel').hidden=!$('#multiPanel').hidden;el.setAttribute('aria-expanded',!$('#multiPanel').hidden);break;case 'selectAll':state.selected=state.selected.size?new Set():new Set(DATA.prompts.map(p=>p.id));renderCompetitive();$('#multiPanel').hidden=false;$('#multiToggle').setAttribute('aria-expanded','true');break;case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen();else if($('#chartCard').requestFullscreen)$('#chartCard').requestFullscreen().catch(()=>toast('La pantalla completa no está disponible en este navegador.'));break;case 'auditHistory':modalShell('Historial de recomendaciones',state.audit.length?state.audit.slice().reverse().map(a=>`<div style="padding:12px 0;border-bottom:1px solid #edf1f7"><b class="small">${esc(a.title)}</b><p class="small muted">${esc(a.from)} → ${esc(a.to)} · ${esc(a.date)}</p></div>`).join(''):'<div class="empty"><h3>Sin cambios en esta sesión</h3><p>Los cambios de estado de las recomendaciones aparecerán aquí.</p></div>');break;case 'retryBI':$('#biContent').innerHTML='<div class="skeleton" style="height:140px"></div>';setTimeout(()=>{$('#biContent')&&(DATA.brandIntelligence.states[state.biMonth]='empty',renderBIContent())},400);break;case 'backLink':e.preventDefault();showProjects();break}});
document.addEventListener('input',e=>{if(e.target.id==='promptSearch'){state.query=e.target.value;state.page=1;const focusPos=e.target.selectionStart;renderPrompts();$('#promptSearch').focus();if($('#promptSearch').type==='text')$('#promptSearch').setSelectionRange(focusPos,focusPos)}});
document.addEventListener('change',e=>{const el=e.target,d=el.dataset;if(d.select){el.checked?state.selected.add(d.select):state.selected.delete(d.select);$('#multiToggle').innerHTML=icon('search')+' '+selectedLabel()+' <span class="muted">⌄</span>';$('#selectAll').textContent=state.selected.size?'Deseleccionar todas':'Seleccionar todas';renderChart();renderHistory()}if(d.recstate){const r=DATA.recommendations.find(r=>r.id===d.recstate);state.audit.push({title:r.title,from:r.status,to:el.value,date:new Date().toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'})});r.status=el.value;renderRecs();toast('Estado actualizado durante esta sesión')}if(el.id==='biMonth'){state.biMonth=el.value;renderBIContent()}if(el.id==='biPrompt'){state.biPrompt=el.value;renderBIContent()}});
document.addEventListener('click',e=>{if(!e.target.closest('.multi')&&$('#multiPanel')){$('#multiPanel').hidden=true;$('#multiToggle').setAttribute('aria-expanded','false')}});
$('#tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();state.tab=e.key==='Home'?0:e.key==='End'?4:(state.tab+(e.key==='ArrowRight'?1:4))%5;render();$('#tab'+state.tab).focus()});
$('#modal').addEventListener('close',()=>lastFocus?.focus());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('resize',()=>{clearTimeout(window.resizeTimer);window.resizeTimer=setTimeout(renderKpis,100)});
renderConfig();renderKpis();render();
